functions.split.setThing:
{
   if(target.type == "头盔" || target.type == "衣服" || target.type == "武器" || target.type == "鞋")
   {
      if(this.item.type != "空格")
      {
         this._parent.backPack.setThing(this.item);
      }
      this.item.setThing(target);
      this.flashInfo();
      return true;
   }
   return false;
}

functions.split.flashInfo:
{
   if(this.item.type == "空格" || this.item.holes == 0 || this.item.hole1 + this.item.hole2 + this.item.hole3 <= 0)
   {
      this.needPrice.text = "";
   }
   else
   {
      this.price = 0;
      if(this.item.holes > 0 && this.item.hole1 > 0)
      {
         this.price += 10;
      }
      if(this.item.holes > 1 && this.item.hole2 > 0)
      {
         this.price += 100;
      }
      if(this.item.holes > 2 && this.item.hole3 > 0)
      {
         this.price += 1000;
      }
      this.needPrice.text = "收费" + this.price + "魔石";
   }
}

